var inp = $input.item.json;
var channel = inp.channel || 'telegram';
var phone = String(inp.phone || inp.chatId || '');
var chatId = inp.chatId || phone;
var textContent = inp.textContent || '';
var firstName = inp.firstName || null;
if (!phone || !textContent) return [];
var SB_URL='https://xfibcjhshpmqkrhlpsoa.supabase.co';var SB_KEY='eyJ-REDACTED-SERVICE-ROLE';
var GEMINI_KEY='AIzaSyAOJUNGg2rMsAOiIWi84g_d4nASuKRRH08';var TG_TOKEN='REDACTED_TELEGRAM_BOT_TOKEN';
var WA_API='https://api.arcadia-tour.cloud';var WA_KEY='863E50B69702-4B1F-B00F-45E76B267DBE';
try{await this.helpers.httpRequest({method:'POST',url:SB_URL+'/rest/v1/leads',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({phone:phone,source:channel,stage:'new',assigned_to:'laila',last_contact:new Date().toISOString(),name:firstName})});}catch(e){}
try{await this.helpers.httpRequest({method:'POST',url:SB_URL+'/rest/v1/conversations',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({phone:phone,role:'user',message:textContent})});}catch(e){}
var rows=[];try{var hist=await this.helpers.httpRequest({method:'GET',url:SB_URL+'/rest/v1/conversations?phone=eq.'+phone+'&order=created_at.asc&limit=15',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY}});rows=Array.isArray(hist)?hist:[];}catch(e){}
var chatHistory=rows.map(function(m){return(m.role==='user'?'العميل':'ليلى')+': '+m.message;}).join('\n');
var SYSTEM='انتِ ليلى، موظفة مبيعات في اركاديا للسياحة. خليجية ودودة ذكية.\nقواعد:\n- سؤال واحد فقط في كل رسالة\n- الوجهات: كازاخستان روسيا بولندا اوزبكستان';
var userMsg=SYSTEM+'\n\nالمحادثة السابقة:\n'+chatHistory+'\n\nرسالة العميل:\n'+textContent;
var reply='اهلاً! كيف اقدر اساعدك؟ 😊';
try{var gr=await this.helpers.httpRequest({method:'POST',url:'https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-pro:generateContent?key='+GEMINI_KEY,headers:{'Content-Type':'application/json'},body:JSON.stringify({contents:[{role:'user',parts:[{text:userMsg}]}],generationConfig:{temperature:0.7,maxOutputTokens:600}})});var pts=(gr&&gr.candidates&&gr.candidates[0]&&gr.candidates[0].content&&gr.candidates[0].content.parts)||[];var draft=pts.map(function(p){return p.text||'';}).join('').trim();if(draft)reply=draft;}catch(e){reply='عذراً، حدث خطأ مؤقت.';}
if(channel==='whatsapp'){try{await this.helpers.httpRequest({method:'POST',url:WA_API+'/message/sendText/h',headers:{apikey:WA_KEY,'Content-Type':'application/json'},body:JSON.stringify({number:phone,textMessage:{text:reply}})});}catch(e){}}else{try{await this.helpers.httpRequest({method:'POST',url:'https://api.telegram.org/bot'+TG_TOKEN+'/sendMessage',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:chatId,text:reply})});}catch(e){}}
try{await this.helpers.httpRequest({method:'POST',url:SB_URL+'/rest/v1/conversations',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({phone:phone,role:'assistant',message:reply})});}catch(e){}
return [{json:{phone:phone,channel:channel,chatId:chatId,response:reply}}];
